/**
 * The knowledge assistant, as the backoffice page reads it (Milestone 7, RAG).
 *
 * One call: `POST /knowledge/query` with the session token, `{ question }` in,
 * `{ answer }` out. The answer is generated by the model from TrackFlow's
 * policies; the page never sees chunks or scores. A reply without a usable
 * answer is an error, so a failure can never look like an empty answer.
 */

import { parseResponseJson, requestAuthenticatedApi } from "@/lib/api-client";
import { describeError, type ErrorCopy } from "@/lib/friendly-error";

export const KNOWLEDGE_PATH = "/knowledge";
const KNOWLEDGE_QUERY_API = "/knowledge/query";

/** Matches `MAX_QUESTION_LENGTH` in `services/knowledge/models.py`. */
export const MAX_QUESTION_LENGTH = 1000;

/** BRIEFING section 1's recurring questions, as starting points. */
export const EXAMPLE_QUESTIONS: readonly string[] = [
  "What's the standard return window?",
  "Which carrier best covers rural Aragón?",
  "How are storage fees calculated?",
  "Is the delivery SLA guaranteed during Black Friday?",
];

export const KNOWLEDGE_ERROR_COPY: ErrorCopy = {
  offline: "Could not reach the knowledge assistant. Check your connection and try again.",
  server:
    "The knowledge assistant is unavailable right now. Please try again in a moment, and contact TrackFlow Tech if it keeps happening.",
};

const UNREADABLE_ANSWER =
  "The knowledge assistant returned an answer this page cannot read. Please try again, and contact TrackFlow Tech if it keeps happening.";

class KnowledgeResponseError extends Error {}

export type KnowledgeAnswer = { answer: string };

export function isKnowledgeAnswer(value: unknown): value is KnowledgeAnswer {
  return (
    typeof value === "object" &&
    value !== null &&
    !Array.isArray(value) &&
    typeof (value as { answer?: unknown }).answer === "string" &&
    (value as { answer: string }).answer.trim().length > 0
  );
}

/** Trimmed question, or null when there is nothing to ask. */
export function normaliseQuestion(question: string): string | null {
  const trimmed = question.trim();
  return trimmed.length > 0 && trimmed.length <= MAX_QUESTION_LENGTH ? trimmed : null;
}

export async function askKnowledgeBase(question: string): Promise<string> {
  const response = await requestAuthenticatedApi(KNOWLEDGE_QUERY_API, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ question }),
    cache: "no-store",
  });
  const value = await parseResponseJson(response);
  if (!isKnowledgeAnswer(value)) {
    throw new KnowledgeResponseError(UNREADABLE_ANSWER);
  }
  return value.answer.trim();
}

export function describeKnowledgeError(error: unknown): string {
  if (error instanceof KnowledgeResponseError) return error.message;
  return describeError(error, "Please check your question and try again.", KNOWLEDGE_ERROR_COPY).message;
}
